import{_ as r,C as o,c as i,o as c,aa as d,G as a}from"./chunks/framework.Cn7WEiMX.js";const f=JSON.parse('{"title":"EarthMC 地图","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/Dynmap/setup/guides/earthmc-maps.md","filePath":"wiki/Dynmap/setup/guides/earthmc-maps.md"}'),s={name:"wiki/Dynmap/setup/guides/earthmc-maps.md"};function n(p,e,m,u,_,h){const l=o("NolebaseGitContributors"),t=o("NolebaseGitChangelog");return c(),i("div",null,[e[0]||(e[0]=d('<h1 id="earthmc-地图" tabindex="-1">EarthMC 地图 <a class="header-anchor" href="#earthmc-地图" aria-label="Permalink to &quot;EarthMC 地图&quot;">​</a></h1> <p>EarthMC 的地图与 Dynmap 有许多已知的兼容性问题：例如渲染不完整，只渲染玩家探索过的区域，或者不渲染树叶等植被。这是地图的制作方式导致的，而不是 Dynmap 本身有问题，不过好在这里有解决方法。</p> <ol><li>下载 WorldBorder 插件：<a href="https://www.spigotmc.org/resources/worldborder.60905/" target="_blank" rel="noreferrer">https://www.spigotmc.org/resources/worldborder.60905/</a></li> <li>暂停地图显示：<code>/dynmap pause all</code></li> <li>设置世界边界半径与中心：<code>/wb [世界名称] set [X 轴半径] [Z 轴半径] {X} {Z}</code></li></ol> <ul><li><code>[世界名称]</code> 为需要设置边界的名称</li> <li><code>[X 轴半径]</code> 为世界的水平半径</li> <li><code>[Z 轴半径]</code> 为世界的垂直半径</li> <li><code>{X}</code> 为世界的水平中心点</li> <li><code>{Z}</code> 为世界的垂直中心点</li></ul> <ol start="4"><li>强制 WorldBorder 开始执行任务：<code>/wb [世界名称] fill [频率] [余量] [强制]</code></li></ol> <ul><li><code>[世界名称]</code> 为需要预生成的世界名称</li> <li><code>[频率]</code> 为每秒生成多少区块，默认为 20。警告：设置太高会导致卡顿。</li> <li><code>[余量]</code> 为在世界边界之外生成多少区块，确保玩家抵达世界边界时还能看见边界以外的区块。默认为 208，不过对于 EarthMC 地图，建议将其设置为 0。</li> <li><code>[强制]</code> 必须设置为 true。</li></ul> <ol start="5"><li>等待预生成完毕。</li></ol> <ul><li>完成之后，输入命令取消暂停：<code>/dynmap pause none</code>，可能需要使用命令 <code>/dynmap fullrender [世界名称]</code> 重新渲染一次地图才会生效。</li></ul> ',16)),a(l),a(t)])}const g=r(s,[["render",n]]);export{f as __pageData,g as default};
